export function UserDashboard({ userId }: { userId: string }) {
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    fetch('/api/user/' + userId)
      .then(res => res.json())
      .then(json => setData(json));
  }); // <-- Remarquez les dépendances

  return <div>{data?.name}</div>;
}

